540→export const diTrackApi = {
541→  /**
542→   * Upload a new DI track (multipart form).
543→   */
544→  async upload(file: File, params: DITrackUploadParams): Promise<DITrack> {
545→    const formData = new FormData();
546→    formData.append('file', file);
547→    formData.append('title', params.title);
548→    if (params.description) {
549→      formData.append('description', params.description);
550→    }
551→    if (params.guitar) {
552→      formData.append('guitar', params.guitar);
553→    }
554→    if (params.pickups) {
555→      formData.append('pickups', params.pickups);
556→    }
557→    if (params.tuning) {
558→      formData.append('tuning', params.tuning);
559→    }
560→    if (params.strings) {
561→      formData.append('strings', params.strings);
562→    }
563→    if (params.recording_interface) {
564→      formData.append('recording_interface', params.recording_interface);
565→    }
566→
567→    const response = await fetch('/api/di-tracks/upload', {
568→      method: 'POST',
569→      body: formData,
570→      credentials: 'include',
571→    });
572→
573→    if (!response.ok) {
574→      // Try to parse JSON error response, fallback to generic HTTP error
575→      const errorData: ApiErrorResponse = await response.json().catch(() => ({
576→        detail: `Upload failed: ${response.statusText}`,
577→      }));
578→
579→      // Extract and sanitize error message using error handling utilities
580→      const sanitizedMessage = getErrorMessage(errorData);
581→
582→      // Extract error code (returns null if not present or invalid format)
583→      const errorCode = extractErrorCode(errorData);
584→
585→      // Extract request_id for support reference
586→      const requestId = extractRequestId(errorData);
587→
588→      // Throw ApiError with sanitized message, code, request_id, and original response
589→      throw new ApiError(sanitizedMessage, errorCode, requestId, errorData);
590→    }
591→
592→    return response.json();
593→  },
594→
595→  /**
596→   * List DI tracks with pagination and optional filtering.
597→   */
598→  list(params: DITrackListParams = {}): Promise<DITrackListResponse> {
599→    const { page = 1, pageSize = 20, guitar, tuning } = params;
600→    const queryParams = new URLSearchParams({
601→      page: String(page),
602→      page_size: String(pageSize),
603→    });
604→    if (guitar) {
605→      queryParams.append('guitar', guitar);
606→    }
607→    if (tuning) {
608→      queryParams.append('tuning', tuning);
609→    }
610→    return api.get<DITrackListResponse>(`/di-tracks?${queryParams.toString()}`);
611→  },
612→
613→  /**
614→   * Get a single DI track by ID.
615→   */
616→  get(id: string): Promise<DITrack> {
617→    return api.get<DITrack>(`/di-tracks/${id}`);
618→  },
619→
620→  /**
621→   * Delete a DI track by ID.
622→   */
623→  delete(id: string): Promise<void> {
624→    return api.delete<void>(`/di-tracks/${id}`);
625→  },
626→};
