  1→/**
  2→ * DITrackSelectModal - Modal for selecting DI tracks in the signal chain builder.
  3→ *
  4→ * Features:
  5→ * - List all DI tracks (user + system)
  6→ * - Search/filter by title
  7→ * - Display track metadata (duration, sample rate, guitar)
  8→ * - Single-click selection closes modal
  9→ */
 10→import { useState, useMemo, useEffect, useCallback } from 'react';
 11→import { Search, X, Loader2, Music } from 'lucide-react';
 12→import { useQuery } from '@tanstack/react-query';
 13→import { diTrackApi, type DITrackListItem } from '@/lib/api';
 14→
 15→interface DITrackSelectModalProps {
 16→  /** Whether the modal is open */
 17→  isOpen: boolean;
 18→  /** Callback to close the modal */
 19→  onClose: () => void;
 20→  /** Callback when a track is selected */
 21→  onSelect: (track: DITrackListItem) => void;
 22→  /** Modal title */
 23→  title?: string;
 24→}
 25→
 26→/** Format duration in seconds to MM:SS */
 27→function formatDuration(seconds: number): string {
 28→  const mins = Math.floor(seconds / 60);
 29→  const secs = Math.floor(seconds % 60);
 30→  return `${mins}:${secs.toString().padStart(2, '0')}`;
 31→}
 32→
 33→/** Format sample rate with kHz suffix */
 34→function formatSampleRate(hz: number): string {
 35→  return `${(hz / 1000).toFixed(1)} kHz`;
 36→}
 37→
 38→export function DITrackSelectModal({
 39→  isOpen,
 40→  onClose,
 41→  onSelect,
 42→  title = 'Select DI Track',
 43→}: DITrackSelectModalProps) {
 44→  const [searchQuery, setSearchQuery] = useState('');
 45→
 46→  // Fetch DI tracks (user's tracks)
 47→  const userTracksQuery = useQuery({
 48→    queryKey: ['di-tracks', 'user'],
 49→    queryFn: () => diTrackApi.list({ pageSize: 100 }),
 50→    enabled: isOpen,
 51→    staleTime: 30000,
 52→  });
 53→
 54→  // Fetch system tracks (available to all users)
 55→  const systemTracksQuery = useQuery({
 56→    queryKey: ['di-tracks', 'system'],
 57→    queryFn: () =>
 58→      // The API uses system_only query param via URLSearchParams
 59→      fetch('/api/di-tracks?page=1&page_size=100&system_only=true', {
 60→        credentials: 'include',
 61→      }).then((res) => {
 62→        if (!res.ok) throw new Error('Failed to fetch system tracks');
 63→        return res.json();
 64→      }),
 65→    enabled: isOpen,
 66→    staleTime: 30000,
 67→  });
 68→
 69→  const isLoading = userTracksQuery.isLoading || systemTracksQuery.isLoading;
 70→  const error = userTracksQuery.error || systemTracksQuery.error;
 71→
 72→  // Combine and deduplicate tracks
 73→  const allTracks = useMemo(() => {
 74→    const userTracks = userTracksQuery.data?.di_tracks ?? [];
 75→    const systemTracks = systemTracksQuery.data?.di_tracks ?? [];
 76→
 77→    // Combine, with user tracks first, then system tracks
 78→    const combined = [...userTracks];
 79→    const userIds = new Set(userTracks.map((t: DITrackListItem) => t.id));
 80→
 81→    for (const track of systemTracks) {
 82→      if (!userIds.has(track.id)) {
 83→        combined.push(track);
 84→      }
 85→    }
 86→
 87→    return combined;
 88→  }, [userTracksQuery.data, systemTracksQuery.data]);
 89→
 90→  // Filter tracks by search query
 91→  const filteredTracks = useMemo(() => {
 92→    if (!searchQuery.trim()) return allTracks;
 93→
 94→    const query = searchQuery.toLowerCase();
 95→    return allTracks.filter((track: DITrackListItem) => {
 96→      const titleMatch = track.title.toLowerCase().includes(query);
 97→      const guitarMatch = track.guitar?.toLowerCase().includes(query);
 98→      const descMatch = track.description?.toLowerCase().includes(query);
 99→      return titleMatch || guitarMatch || descMatch;
100→    });
101→  }, [allTracks, searchQuery]);
102→
103→  // Handle track selection
104→  const handleSelect = useCallback(
105→    (track: DITrackListItem) => {
106→      onSelect(track);
107→      onClose();
108→    },
109→    [onSelect, onClose]
110→  );
111→
112→  // Handle escape key
113→  useEffect(() => {
114→    const handleKeyDown = (e: KeyboardEvent) => {
115→      if (e.key === 'Escape') {
116→        onClose();
117→      }
118→    };
119→
120→    if (isOpen) {
121→      document.addEventListener('keydown', handleKeyDown);
122→      document.body.style.overflow = 'hidden';
123→    }
124→
125→    return () => {
126→      document.removeEventListener('keydown', handleKeyDown);
127→      document.body.style.overflow = '';
128→    };
129→  }, [isOpen, onClose]);
130→
131→  if (!isOpen) return null;
132→
133→  return (
134→    <div className="fixed inset-0 z-50 flex items-center justify-center">
135→      {/* Backdrop */}
136→      <div
137→        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
138→        onClick={onClose}
139→        aria-hidden="true"
140→      />
141→
142→      {/* Modal */}
143→      <div className="relative z-10 flex max-h-[90vh] w-full max-w-2xl flex-col rounded-lg border border-border bg-card shadow-xl">
144→        {/* Header */}
145→        <div className="flex items-center justify-between border-b border-border px-6 py-4">
146→          <h2 className="text-lg font-semibold text-foreground">{title}</h2>
147→          <button
148→            type="button"
149→            onClick={onClose}
150→            className="rounded p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
151→            aria-label="Close modal"
152→          >
153→            <X className="h-5 w-5" />
154→          </button>
155→        </div>
156→
157→        {/* Search */}
158→        <div className="border-b border-border px-6 py-4">
159→          <div className="relative">
160→            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
161→            <input
162→              type="text"
163→              placeholder="Search DI tracks..."
164→              value={searchQuery}
165→              onChange={(e) => setSearchQuery(e.target.value)}
166→              className="h-10 w-full rounded-md border border-input bg-background pl-9 pr-3 text-sm focus:border-[var(--color-block-di)] focus:outline-none focus:ring-1 focus:ring-[var(--color-block-di)]"
167→              autoFocus
168→            />
169→          </div>
170→        </div>
171→
172→        {/* Results */}
173→        <div className="flex-1 overflow-y-auto">
174→          {isLoading ? (
175→            <div className="flex h-64 items-center justify-center">
176→              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
177→            </div>
178→          ) : error ? (
179→            <div className="flex h-64 flex-col items-center justify-center gap-2 text-muted-foreground">
180→              <p className="text-sm">Failed to load DI tracks</p>
181→            </div>
182→          ) : filteredTracks.length === 0 ? (
183→            <div className="flex h-64 flex-col items-center justify-center gap-3 text-muted-foreground">
184→              <Music className="h-12 w-12 text-[var(--color-block-di)]" />
185→              <p className="text-sm">
186→                {searchQuery ? 'No matching tracks found' : 'No DI tracks available'}
187→              </p>
188→              {!searchQuery && (
189→                <a
190→                  href="/library/di-tracks"
191→                  className="text-sm text-[var(--color-accent-primary)] hover:underline"
192→                >
193→                  Upload a DI track
194→                </a>
195→              )}
196→            </div>
197→          ) : (
198→            <div className="divide-y divide-border">
199→              {filteredTracks.map((track: DITrackListItem) => (
200→                <button
201→                  key={track.id}
202→                  type="button"
203→                  onClick={() => handleSelect(track)}
204→                  className="flex w-full items-start gap-4 px-6 py-4 text-left transition-colors hover:bg-muted/50"
205→                >
206→                  {/* Track icon */}
207→                  <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[var(--color-block-di)]/20">
208→                    <Music className="h-5 w-5 text-[var(--color-block-di)]" />
209→                  </div>
210→
211→                  {/* Track info */}
212→                  <div className="min-w-0 flex-1">
213→                    <h4 className="truncate font-medium text-foreground">
214→                      {track.title}
215→                    </h4>
216→                    <p className="mt-0.5 text-sm text-muted-foreground">
217→                      {formatDuration(track.duration_seconds)} ·{' '}
218→                      {formatSampleRate(track.sample_rate)}
219→                      {track.guitar && ` · ${track.guitar}`}
220→                    </p>
221→                    {track.description && (
222→                      <p className="mt-1 truncate text-sm text-muted-foreground/70">
223→                        {track.description}
224→                      </p>
225→                    )}
226→                  </div>
227→
228→                  {/* System track badge */}
229→                  {track.is_system_track && (
230→                    <span className="shrink-0 rounded-full bg-[var(--color-block-di)]/20 px-2 py-0.5 text-xs font-medium text-[var(--color-block-di)]">
231→                      System
232→                    </span>
233→                  )}
234→                </button>
235→              ))}
236→            </div>
237→          )}
238→        </div>
239→
240→        {/* Footer */}
241→        <div className="border-t border-border px-6 py-3">
242→          <p className="text-sm text-muted-foreground">
243→            {filteredTracks.length} track{filteredTracks.length !== 1 ? 's' : ''} available
244→          </p>
245→        </div>
246→      </div>
247→    </div>
248→  );
249→}
